  const cache = new Map();
  function canvas(name) {
    if (cache.has(name)) return cache.get(name);
    const item = DATA[name];
    if (!item) return null;
    const out = document.createElement("canvas");
    out.width = item.w;
    out.height = item.h;
    const ctx = out.getContext("2d", { alpha: true });
    const image = ctx.createImageData(item.w, item.h);
    const packedPixels = atob(item.p);
    for (let i = 0; i < packedPixels.length; i++) {
      const paletteIndex = packedPixels.charCodeAt(i);
      if (!paletteIndex) continue;
      const color = item.c[paletteIndex - 1];
      const offset = i * 4;
      image.data[offset] = color >>> 16;
      image.data[offset + 1] = (color >>> 8) & 255;
      image.data[offset + 2] = color & 255;
      image.data[offset + 3] = 255;
    }
    ctx.putImageData(image, 0, 0);
    cache.set(name, out);
    return out;
  }
  window.FurPixelSprites = { canvas, has: (name) => Boolean(DATA[name]) };
